int64 compute_gcd(int64 x, int64 y) {
    if (x < y) swap(x, y);
    while (y != 0) {
        x %= y;
        swap(x, y);
    }
    return x;
}

int64 compute_lcm(int64 x, int64 y) {
    return x / compute_gcd(x, y) * y;
}

